import {ActionMenu, ActionList} from '@primer/react'

import styles from './UsageChart.module.css'
import type {UsageChartSelection} from '../../types/usage'

export interface UsageChartFilterProps {
  selectedGranularity: UsageChartSelection | undefined
  onGranularityChange: (granularity: UsageChartSelection) => void
  availableOptions: UsageChartSelection[]
  isLoading?: boolean
}

export function UsageChartFilter({
  selectedGranularity,
  onGranularityChange,
  availableOptions,
  isLoading = false,
}: UsageChartFilterProps) {
  return (
    <div className={isLoading ? styles.granularitySelectorHidden : styles.granularitySelector}>
      <ActionMenu>
        <ActionMenu.Button>Granularity: {selectedGranularity?.displayText}</ActionMenu.Button>
        <ActionMenu.Overlay>
          <ActionList selectionVariant="single" role="menu" aria-label="Granularity">
            {availableOptions.map(option => (
              <ActionList.Item
                key={option.displayText}
                role="menuitemradio"
                selected={option === selectedGranularity}
                aria-checked={option === selectedGranularity}
                onSelect={() => onGranularityChange(option)}
              >
                {option.displayText}
              </ActionList.Item>
            ))}
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>
    </div>
  )
}
