import {VisuallyHidden} from '@primer/react'
import {useEffect, useState, useMemo, useCallback, type ReactNode} from 'react'
import {ErrorBoundary} from '@github-ui/react-core/error-boundary'

import styles from './UsageChart.module.css'

import {ChartCard} from '@github-ui/chart-card'

import {ErrorComponent, LoadingComponent, NoDataComponent} from '..'
import {UsageChartFilter} from './UsageChartFilter'

import {RequestState, UsagePeriod} from '../../enums'
import {getPeriodText, getUsageChartTitle} from '../../utils'
import {
  USAGE_CHART_SELECTION_DAILY,
  USAGE_CHART_SELECTION_MONTHLY,
  MONTHLY_PERIOD_CHART_OPTIONS,
  YEARLY_PERIOD_CHART_OPTIONS,
} from '../../constants/chart'

import type {Filters, UsageChartData, UsageChartSelection} from '../../types/usage'
import useModelsData from '../../hooks/models/use-models-data'

interface CustomPoint extends Highcharts.Point {
  custom?: {
    grossAmount?: string
    totalAmount?: string
    discountAmount?: string
  }
}

function createValueDescriptionFormatter(billedLabel: string) {
  return function (point: CustomPoint) {
    const date = new Date(point.x)
    const options: Intl.DateTimeFormatOptions = {
      weekday: 'long',
      day: 'numeric',
      month: 'short',
      year: 'numeric',
      timeZone: 'UTC',
    }
    const formattedDate = date.toLocaleDateString('en-US', options).replace(/,(\s\d{4})/, '$1')

    return `Usage ${formattedDate}, Gross: ${point.custom?.grossAmount} ${billedLabel}: ${point.custom?.totalAmount} Discount: ${point.custom?.discountAmount}.`
  }
}

function createTooltipPointFormatter(billedLabel: string) {
  return function (this: CustomPoint) {
    const grossAmount = this.custom?.grossAmount
    const totalAmount = this.custom?.totalAmount
    const discountAmount = this.custom?.discountAmount

    // eslint-disable-next-line github/unescaped-html-literal
    return `<tr><td style="padding-top:var(--base-size-4)"><span style="color:${this.color}">●</span> Gross:</td><td style="text-align: right; padding-top:var(--base-size-4);"><strong>${grossAmount}</strong></td></tr><tr><td style="padding-top:var(--base-size-4); padding-left:16px"> ${billedLabel}:</td><td style="text-align: right; padding-top:var(--base-size-4);"><strong>${totalAmount}</strong></td></tr><tr><td style="padding-top:var(--base-size-4); padding-left:16px"> Discount:</td><td style="text-align: right; padding-top:var(--base-size-4);"><strong>${discountAmount}</strong></td></tr>`
  }
}

function getChartPeriod(filters: Filters) {
  switch (filters.period?.type) {
    case UsagePeriod.THIS_YEAR:
    case UsagePeriod.LAST_YEAR: {
      return 30 * 24 * 3600 * 1000 // month
    }
    case UsagePeriod.THIS_MONTH:
    case UsagePeriod.LAST_MONTH: {
      return 24 * 3600 * 1000 // day
    }
    default: {
      return 24 * 3600 * 1000 // day
    }
  }
}

function getTooltipLabel(filters: Filters) {
  switch (filters.period?.type) {
    case UsagePeriod.THIS_YEAR:
    case UsagePeriod.LAST_YEAR: {
      return 'in %b %Y' // month
    }
    case UsagePeriod.THIS_MONTH:
    case UsagePeriod.LAST_MONTH: {
      return 'on %b %e, %Y' // day
    }
    default: {
      return '%b %e, %Y' // day
    }
  }
}

function getXAxisLabel(filters: Filters) {
  switch (filters.period?.type) {
    case UsagePeriod.THIS_YEAR:
    case UsagePeriod.LAST_YEAR: {
      return '{value:%b}' // month
    }
    case UsagePeriod.THIS_MONTH:
    case UsagePeriod.LAST_MONTH: {
      return '{value:%b %e}' // month day
    }
    default: {
      return '{value:%b %e}' // month day
    }
  }
}

interface UsageChartProps {
  filters: Filters
  requestState: RequestState
  usage: UsageChartData[]
  // Used to add children alongside the usage actions component.
  children?: ReactNode
  copilotVariant?: boolean
  noneGroupingTitle?: string
  billedLabel?: string
  onFiltersChange?: (filters: Filters) => void
}

const isLoadingStates = new Set<RequestState>([RequestState.INIT, RequestState.LOADING])

// These values are defined by Highcharts, the library used for the ChartCard component.
// https://api.highcharts.com/class-reference/Highcharts#.DashStyleValue
const DASH_STYLES = [
  'Solid',
  'ShortDash',
  'ShortDot',
  'ShortDashDot',
  'ShortDashDotDot',
  'Dot',
  'Dash',
  'LongDash',
  'DashDot',
  'LongDashDot',
  'LongDashDotDot',
] as const

export function UsageChart({
  filters,
  requestState,
  usage,
  children,
  copilotVariant,
  noneGroupingTitle,
  billedLabel = 'Billed',
  onFiltersChange,
}: UsageChartProps) {
  const [screenReaderAnnouncement, setScreenReaderAnnouncement] = useState<string>('')
  const isMonthlyRequest =
    filters.period?.type === UsagePeriod.LAST_MONTH || filters.period?.type === UsagePeriod.THIS_MONTH

  const availableOptions: UsageChartSelection[] = useMemo(
    () => (isMonthlyRequest ? MONTHLY_PERIOD_CHART_OPTIONS : YEARLY_PERIOD_CHART_OPTIONS),
    [isMonthlyRequest],
  )

  const getDefaultGranularity = useCallback((): UsageChartSelection => {
    if (isMonthlyRequest) {
      return USAGE_CHART_SELECTION_DAILY
    } else {
      return USAGE_CHART_SELECTION_MONTHLY
    }
  }, [isMonthlyRequest])

  const defaultOption = getDefaultGranularity()

  const selectedFilter: UsageChartSelection =
    filters.chartSelection &&
    availableOptions.some(option => option.displayText === filters.chartSelection?.displayText)
      ? filters.chartSelection
      : defaultOption

  const handleFilterChange = (filter: UsageChartSelection) => {
    if (onFiltersChange) {
      onFiltersChange({
        ...filters,
        chartSelection: filter,
      })
    }
  }

  const valueDescriptionFormatter = useMemo(() => createValueDescriptionFormatter(billedLabel), [billedLabel])
  const tooltipPointFormatter = useMemo(() => createTooltipPointFormatter(billedLabel), [billedLabel])

  const modelsData = useModelsData({filters})
  const modelsMap = useMemo(() => {
    const map: Record<string, string> = {}
    if (modelsData.modelsData && Array.isArray(modelsData.modelsData)) {
      for (const modelObj of modelsData.modelsData) {
        map[modelObj.model] = modelObj.formattedModel || modelObj.model
      }
    }
    return map
  }, [modelsData.modelsData])

  // Reset to period-appropriate default when period changes and current selection is invalid
  useEffect(() => {
    // Only update if current selection is invalid for new period to avoid unnecessary requests
    if (
      filters.chartSelection &&
      !availableOptions.some(option => option.displayText === filters.chartSelection?.displayText)
    ) {
      if (onFiltersChange) {
        const newDefaultOption = getDefaultGranularity()
        onFiltersChange({
          ...filters,
          chartSelection: newDefaultOption,
        })
      }
    }
  }, [isMonthlyRequest, onFiltersChange, filters, availableOptions, getDefaultGranularity])

  useEffect(() => {
    if (isLoadingStates.has(requestState)) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setScreenReaderAnnouncement('Loading usage data...')
    } else if (requestState === RequestState.ERROR) {
      setScreenReaderAnnouncement('Error loading usage data.')
    } else if (requestState === RequestState.IDLE) {
      if (!usage || usage.length === 0) {
        setScreenReaderAnnouncement('No usage data found for the selected filters.')
      } else {
        const title = getUsageChartTitle(filters, copilotVariant, modelsMap, noneGroupingTitle)
        const period = filters.period?.displayText || 'selected period'
        const dataPoints = usage.reduce((sum, dataset) => sum + dataset.data.length, 0)
        setScreenReaderAnnouncement(`${title} chart showing data for ${period}. ${dataPoints} data points found.`)
      }
    }
  }, [requestState, usage, filters, copilotVariant, modelsMap, noneGroupingTitle])

  const usageLength = usage.length && usage[0]?.data?.length ? usage[0].data.length : 0
  const chartLoaded = requestState === RequestState.IDLE && usageLength > 0
  const usageChartStartDate = usage[0]?.data[0]?.x
  return (
    <div data-hpc>
      <VisuallyHidden role="status">{screenReaderAnnouncement}</VisuallyHidden>
      <ErrorBoundary
        fallback={
          <div className="tmp-mb-3">
            <ChartCard size="xl" border>
              <ChartCard.Title>
                {getUsageChartTitle(filters, copilotVariant, modelsMap, noneGroupingTitle)}
              </ChartCard.Title>
              <ChartCard.Description>{getPeriodText(filters.period)}</ChartCard.Description>
              <ErrorComponent
                className={styles.innerContainer}
                testid="usage-chart-error-boundary"
                text="Unable to load chart"
              />
            </ChartCard>
          </div>
        }
        appName="billing-app"
      >
        <div className={styles.mobileOnly}>{children}</div>
        <div className={chartLoaded ? '' : styles.container}>
          {!chartLoaded && (
            <div className={styles.chartHeaderContainer}>
              <div>
                <h2 className={styles.chartTitle} id="usage-chart-title" data-testid="usage-chart-title">
                  {getUsageChartTitle(filters, copilotVariant, modelsMap, noneGroupingTitle)}
                </h2>
                <span className={styles.chartSubtitle} id="usage-chart-subtitle" data-testid="usage-chart-subtitle">
                  {getPeriodText(filters.period)}
                </span>
              </div>
              <div className={styles.desktopOnly}>{children}</div>
            </div>
          )}

          <div className="tmp-mb-3">
            {isLoadingStates.has(requestState) && (
              <LoadingComponent className={styles.innerContainerStyle} testid="usage-loading-spinner" />
            )}
            {requestState === RequestState.ERROR && (
              <ErrorComponent
                className={styles.innerContainer}
                testid="usage-loading-error"
                text="Something went wrong"
              />
            )}
            {requestState === RequestState.IDLE && (
              <>
                {usageLength === 0 && (
                  <NoDataComponent className={styles.innerContainer} testid="no-usage-data" text="No usage found" />
                )}
                {usageLength > 0 && (
                  <ChartCard size="xl" border>
                    <ChartCard.Title as="h2" className={styles.chartTitle}>
                      {getUsageChartTitle(filters, copilotVariant, modelsMap, noneGroupingTitle)}
                    </ChartCard.Title>
                    <ChartCard.Description>{getPeriodText(filters.period)}</ChartCard.Description>
                    <ChartCard.TrailingVisual>
                      {copilotVariant && (
                        <div className={styles.trailingVisualContainer}>
                          <UsageChartFilter
                            selectedGranularity={selectedFilter}
                            availableOptions={availableOptions}
                            isLoading={false}
                            onGranularityChange={handleFilterChange}
                          />
                        </div>
                      )}
                      <div className={styles.desktopOnly}>{children}</div>
                    </ChartCard.TrailingVisual>
                    <ChartCard.Chart
                      series={usage.map((dataset, index) => {
                        const baseDataset = {
                          ...dataset,
                          type: 'line',
                        }
                        // Only apply different dash styles for copilot variant
                        if (copilotVariant) {
                          return {
                            ...baseDataset,
                            // use modulo to ensure we don't go out of bounds and we cycle through DASH_STYLES array when needed.
                            dashStyle: DASH_STYLES[index % DASH_STYLES.length],
                          }
                        }
                        return baseDataset
                      })}
                      xAxisTitle={'Time'}
                      yAxisTitle={'Billing'}
                      xAxisOptions={{
                        type: 'datetime',
                        labels: {
                          format: getXAxisLabel(filters),
                        },
                        title: {
                          text: null,
                        },
                        gridLineDashStyle: 'Solid',
                      }}
                      yAxisOptions={{
                        allowDecimals: false,
                        labels: {
                          format: '${value:,.0f}',
                        },
                        gridLineDashStyle: 'Solid',
                        title: {
                          text: null,
                        },
                      }}
                      plotOptions={{
                        series: {
                          pointStart: usageChartStartDate,
                          pointInterval: getChartPeriod(filters),
                          marker: {
                            enabled: usageLength === 1,
                          },
                        },
                      }}
                      type={'line'}
                      overrideOptionsNotRecommended={{
                        chart: {
                          spacingLeft: 5,
                        },
                        legend: {
                          enabled: true,
                          margin: 16,
                          align: 'left',
                          layout: 'horizontal',
                          verticalAlign: 'top',
                          floating: false,
                          maxHeight: 64,
                        },
                        tooltip: {
                          dateTimeLabelFormats: {
                            millisecond: getTooltipLabel(filters),
                          },
                          // eslint-disable-next-line github/unescaped-html-literal
                          headerFormat: '<table><tr><th colspan="2">{series.name} {point.key}</th></tr>',
                          pointFormatter: tooltipPointFormatter,
                        },
                        accessibility: {
                          keyboardNavigation: {order: ['legend', 'series']},
                          point: {
                            descriptionFormatter: valueDescriptionFormatter,
                          },
                        },
                      }}
                    />
                  </ChartCard>
                )}
              </>
            )}
          </div>
        </div>
      </ErrorBoundary>
    </div>
  )
}

export default UsageChart
